-- lifetimes.sql — нормативная периодичность ТО/ТР/КР для ref.norm_period
-- (013_setpoints.sql). Задача MOS-23 (Q2.2).
--
-- Источник — ЦЕЛИКОМ массив "schedule" из code/reglament_to_schedule.json,
-- 54 строки, без отбора и без добавленных чисел: это готовая расшифровка
-- глав 10-17, 21, 24 Регламента (ОПС трёх типов, АКМ, СДУК, СКУД, видео,
-- оповещение, телевидение, информационные системы включая СМВУ, КИП,
-- переносной контроль газовоздушной среды). Беру весь массив, а не
-- подмножество, потому что задача просила «залить нормативы ТО» без
-- ограничения по системам, а отбирать вручную — значит решать за
-- составителя выгрузки, какая система важнее.
--
-- Этим сидом закрываются два конкретных примера приёмки, docs/acceptance-test.md
-- разд. II.3:
--   * НФ-66 — датчики метана ДМТ-6 (id akm-dmt6-to, 60 суток) и «СИГМА-1»/
--     БСМ/ТК-1 (id akm-sigma-bsm-tk1-to, 60 суток): «1 раз в 2 месяца»,
--     дословно совпадает с табл. 11.1 регламента, на которую ссылается тест;
--   * Ф-67 — periodicity_days оборудования СКУД (id skud-eq-to) сейчас 30
--     (1 раз в месяц), тест приёмки меняет его на 2 месяца: `UPDATE
--     ref.norm_period SET periodicity_days = 60, periodicity_text =
--     '1 раз в 2 месяца' WHERE id = 'skud-eq-to';` — план-график должен
--     пересчитаться без пересборки образа, это и есть «редактируемый
--     справочник», а не константа в коде.
--
-- Пять строк содержат note — не выдуманная неопределённость, а дословно
-- перенесённая оговорка составителя выгрузки о качестве распознавания PDF
-- (например akm-as-blocks-to: две строки таблицы слиты в одну ячейку при
-- распознавании). Где note NULL — у составителя оговорок не было.
--
-- Не включён массив "repair_deadlines" из того же файла: это не периодичность
-- ТО, а срок УСТРАНЕНИЯ уже случившейся неисправности по категории (НФ-63…
-- НФ-65) — другая приёмочная строка и, по-хорошему, отдельная задача
-- заявок (Q6), не наш ref.norm_period.
--
-- Накатывать после 013_setpoints.sql:
--   docker compose exec -T db psql -U moskollektor -d moskollektor -f /dev/stdin < db/seed/lifetimes.sql


ON CONFLICT (id) DO UPDATE SET
    system_name       = excluded.system_name,
    equipment         = excluded.equipment,
    work_type         = excluded.work_type,
    periodicity_days  = excluded.periodicity_days,
    periodicity_text  = excluded.periodicity_text,
    clause            = excluded.clause,
    note              = excluded.note;
